window.QUESTION_POOLS = window.QUESTION_POOLS || {};
window.QUESTION_POOLS['techplus'] = [
  { q: 'Which component is considered the "brain" of a computer?', opts: ['RAM', 'CPU', 'GPU', 'SSD'], answer: 1, exp: 'The CPU (Central Processing Unit) executes program instructions and is the primary processing component of any computer.', domain: 'D2' },
  { q: 'What type of memory loses its contents when power is removed?', opts: ['SSD', 'HDD', 'RAM', 'ROM'], answer: 2, exp: 'RAM (Random Access Memory) is volatile — its contents are lost when power is removed. SSDs and HDDs are non-volatile.', domain: 'D2' },
  { q: 'Which of the following is an example of an OUTPUT device?', opts: ['Keyboard', 'Mouse', 'Scanner', 'Monitor'], answer: 3, exp: 'Output devices present data FROM the computer TO the user. Keyboards, mice, and scanners are input devices. Monitors display output.', domain: 'D1' },
  { q: 'What does SQL stand for?', opts: ['Structured Query Language', 'Simple Queue Logic', 'System Query Loader', 'Sequential Question Library'], answer: 0, exp: 'SQL (Structured Query Language) is used to manage and manipulate relational databases with commands like SELECT, INSERT, UPDATE, and DELETE.', domain: 'D5' },
  { q: 'Which cloud service model provides virtual machines and storage — giving customers the most control?', opts: ['SaaS', 'PaaS', 'IaaS', 'DBaaS'], answer: 2, exp: 'IaaS (Infrastructure as a Service) provides virtualized computing resources — VMs, storage, networking. Customers manage the OS and apps.', domain: 'D2' },
  { q: 'A student receives an email claiming to be from school IT asking for their password. This is an example of:', opts: ['Malware', 'DDoS', 'Phishing', 'SQL Injection'], answer: 2, exp: 'Phishing uses fraudulent messages to trick users into revealing credentials. Legitimate IT staff will NEVER ask for your password via email.', domain: 'D6' },
  { q: 'What is the primary purpose of an operating system?', opts: ['To connect to the internet', 'To manage hardware and provide services for applications', 'To store user files permanently', 'To display graphics on screen'], answer: 1, exp: 'The OS manages hardware resources (CPU, memory, storage) and provides a platform for applications to run on.', domain: 'D3' },
  { q: 'Which numbering system uses only 0 and 1?', opts: ['Decimal', 'Hexadecimal', 'Octal', 'Binary'], answer: 3, exp: 'Binary is the base-2 number system that computers use internally. All digital data is ultimately stored as sequences of 0s and 1s.', domain: 'D1' },
  { q: 'How many bits are in one byte?', opts: ['4', '16', '8', '32'], answer: 2, exp: '1 byte = 8 bits. A byte can represent 256 different values (2^8). This is the fundamental unit of digital storage measurement.', domain: 'D1' },
  { q: 'What does a firewall primarily protect against?', opts: ['Physical theft', 'Unauthorized network access', 'Hardware failure', 'Power outages'], answer: 1, exp: 'A firewall monitors and controls network traffic based on security rules, protecting against unauthorized network access and malicious traffic.', domain: 'D6' },
  { q: 'What is the difference between a virus and a worm?', opts: ['A virus encrypts files; a worm deletes them', 'A virus needs a host file and user action to spread; a worm self-spreads across networks automatically', 'A virus targets hardware; a worm targets software', 'They are the same thing'], answer: 1, exp: 'Viruses attach to files and require user action (opening the file) to spread. Worms are self-replicating and spread automatically across networks without any user interaction — like WannaCry.', domain: 'D6' },
  { q: 'Which storage type is the fastest for reading and writing data?', opts: ['HDD (Hard Disk Drive)', 'SSD (SATA)', 'NVMe SSD (PCIe)', 'USB Flash Drive'], answer: 2, exp: 'NVMe SSDs connect via PCIe and can reach 5,000+ MB/s. SATA SSDs top out around 550 MB/s. HDDs spin at 100-200 MB/s. NVMe is the fastest consumer storage available.', domain: 'D2' },
  { q: 'A company stores customer data in the cloud instead of on their own servers. What type of cloud deployment is this MOST likely?', opts: ['Private cloud', 'Public cloud', 'On-premises', 'Hybrid cloud'], answer: 1, exp: 'Public cloud (AWS, Azure, Google Cloud) provides shared infrastructure available to anyone over the internet. Private cloud is dedicated to one organization. Hybrid mixes both.', domain: 'D2' },
  { q: 'What does MFA (Multi-Factor Authentication) require?', opts: ['A very long password', 'Two or more different types of verification (something you know + something you have/are)', 'Changing your password every 30 days', 'A VPN connection'], answer: 1, exp: 'MFA requires 2+ verification factors from different categories: something you know (password), something you have (phone/token), or something you are (fingerprint/face). Even if a password is stolen, MFA blocks attackers.', domain: 'D6' },
  { q: 'In programming, what does a loop do?', opts: ['Connects to the internet', 'Stores a value for later use', 'Repeats a block of code multiple times', 'Makes a decision between two options'], answer: 2, exp: 'Loops (for, while) repeat a block of code. Example: a for loop that runs 10 times to process 10 items in a list. Without loops, programmers would have to write the same code 10 times manually.', domain: 'D4' },
  { q: 'Which SQL command is used to RETRIEVE data from a database table?', opts: ['INSERT', 'UPDATE', 'SELECT', 'DELETE'], answer: 2, exp: 'SELECT retrieves data. INSERT adds new records. UPDATE modifies existing data. DELETE removes records. SELECT is the most commonly used SQL command — "SELECT * FROM students" gets all student records.', domain: 'D5' },
  { q: 'What is RAM primarily used for?', opts: ['Storing your files permanently', 'Running the operating system installer', 'Holding active program data the CPU is currently using', 'Connecting to Wi-Fi networks'], answer: 2, exp: 'RAM is fast, temporary workspace. When you open Chrome, it loads into RAM so the CPU can access it in nanoseconds. More RAM = more programs open at once. When you shut down, RAM is cleared.', domain: 'D2' },
  { q: 'A student opens their laptop and the screen shows nothing, but they can hear it starting up. What should they check first?', opts: ['Replace the CPU', 'Check that the screen brightness is not turned all the way down', 'Reinstall Windows', 'Replace the RAM'], answer: 1, exp: 'Screen brightness being at zero is the most common and simplest cause of an apparently blank screen when the device is clearly running. Always check the simplest explanations first (fn + brightness key).', domain: 'D2' },
  { q: 'What does an algorithm ALWAYS have?', opts: ['Variables and functions', 'A defined start, step-by-step instructions, and a defined end', 'At least one loop and one condition', 'Connection to a database'], answer: 1, exp: 'Every algorithm has: a clear starting point, a finite set of steps, and a stopping condition (it must eventually end). A recipe is a real-world algorithm — it has a start, defined steps, and ends when the dish is complete.', domain: 'D4' },
  { q: 'Which of the following BEST describes the Internet?', opts: ['A private network used only by governments', 'A global network of interconnected computers and networks', 'The same as Wi-Fi', 'A type of operating system'], answer: 1, exp: 'The Internet is a global system of interconnected networks. Wi-Fi is just a wireless technology to connect to a local network. The Internet is what that local network connects to. They are not the same thing.', domain: 'D2' },
  { q: 'What type of software is an antivirus program?', opts: ['Application software', 'System/utility software', 'Database software', 'Development software'], answer: 1, exp: 'Antivirus is system/utility software — it manages and protects the system rather than performing end-user productivity tasks. Application software (like Word or Chrome) is designed for user tasks, not system management.', domain: 'D3' },
  { q: 'How many unique values can 1 byte (8 bits) represent?', opts: ['8', '16', '128', '256'], answer: 3, exp: '2^8 = 256. One byte can represent 256 different values (0-255). This is why IPv4 addresses have numbers from 0-255 in each octet — each octet is one byte.', domain: 'D1' },
  { q: 'A website uses HTTPS instead of HTTP. What does this mean?', opts: ['The website loads faster', 'The connection between your browser and the website is encrypted', 'The website requires a login', 'The website is government-approved'], answer: 1, exp: 'HTTPS uses TLS encryption to secure the connection between your browser and the server. Without it (HTTP), anyone on the same network can read your data in plaintext. HTTPS is essential for any site handling passwords or payments.', domain: 'D6' },
  { q: 'Which component connects all other computer components together?', opts: ['CPU', 'RAM', 'Motherboard', 'GPU'], answer: 2, exp: 'The motherboard is the main circuit board that physically and electronically connects all components: CPU, RAM, storage, GPU, expansion cards, and I/O ports. Everything connects through the motherboard.', domain: 'D2' },
  { q: 'What is the purpose of an operating system\'s file system?', opts: ['To connect to the internet', 'To organize and manage how files are stored and retrieved on storage devices', 'To run antivirus scans', 'To manage Wi-Fi connections'], answer: 1, exp: 'The file system (NTFS, APFS, ext4, FAT32) organizes data into files and folders on storage devices and handles reading/writing data. Without a file system, storage would be an unorganized sequence of bits.', domain: 'D3' },
  { q: 'Which unit of measurement is the LARGEST?', opts: ['Kilobyte (KB)', 'Megabyte (MB)', 'Gigabyte (GB)', 'Terabyte (TB)'], answer: 3, exp: 'From smallest to largest: byte, KB, MB, GB, TB, PB. A terabyte equals roughly 1,000 gigabytes. Common storage today is often measured in TB.', domain: 'D1' },
  { q: 'A student is choosing a password. Which of the following is the STRONGEST?', opts: ['password123', 'P@ssword!', 'MyDog2010', 'BlueCoffee!River42Sunset'], answer: 3, exp: 'Length is the most important factor in password strength. A long passphrase made of random unrelated words is far harder to crack than a short complex password.', domain: 'D6' },
  { q: 'What is a MAC address?', opts: ['A logical address assigned by a router', 'A physical hardware address burned into a network card', 'A type of Apple computer identifier', 'A password used to connect to Wi-Fi'], answer: 1, exp: 'A MAC (Media Access Control) address is a unique 48-bit hardware identifier permanently assigned to each network interface card. It is used at the data link layer of a network.', domain: 'D2' },
  { q: 'Which of the following is a relational database management system?', opts: ['Microsoft Word', 'MySQL', 'Google Chrome', 'Windows 11'], answer: 1, exp: 'MySQL is a relational database management system that stores data in tables with rows and columns. Other examples include PostgreSQL, Microsoft SQL Server, and Oracle.', domain: 'D5' },
  { q: 'A user wants to make documents accessible to people who are blind. Which assistive technology is MOST appropriate?', opts: ['High-contrast color scheme', 'Screen reader software', 'On-screen keyboard', 'Voice dictation'], answer: 1, exp: 'Screen reader software (like JAWS or NVDA) reads on-screen text aloud, allowing blind users to navigate computers and read documents. High-contrast helps users with low vision but not blindness.', domain: 'D3' },
  { q: 'Which file extension typically indicates a compressed archive?', opts: ['.docx', '.zip', '.mp4', '.html'], answer: 1, exp: 'A .zip file is a compressed archive containing one or more files. Compression reduces file size for storage and transfer. Other archive formats include .rar, .7z, and .tar.gz.', domain: 'D3' },
  { q: 'In a flowchart, which shape is used to represent a decision point?', opts: ['Rectangle', 'Oval', 'Diamond', 'Parallelogram'], answer: 2, exp: 'A diamond represents a decision (yes/no, true/false branch). Rectangles represent processes, ovals represent start/end, and parallelograms represent input/output.', domain: 'D4' },
  { q: 'A school sets up a network that covers only the campus buildings. What type of network is this?', opts: ['PAN (Personal Area Network)', 'LAN (Local Area Network)', 'WAN (Wide Area Network)', 'MAN (Metropolitan Area Network)'], answer: 1, exp: 'A LAN connects devices within a limited area such as a single building or campus. WANs cover large geographic regions like the internet. PANs cover a few meters around a single person.', domain: 'D2' },
  { q: 'What does it mean for software to be open-source?', opts: ['It is free of charge only', 'Its source code is publicly available and may be modified and shared', 'It cannot be used commercially', 'It runs only on Linux'], answer: 1, exp: 'Open-source software publishes its source code under a license that allows users to view, modify, and redistribute it. Examples include Linux, Firefox, and LibreOffice. Open-source is not the same as free.', domain: 'D3' },
  { q: 'A user wants to share their internet connection from their phone to their laptop using Wi-Fi. What is this feature called?', opts: ['Bluetooth pairing', 'Mobile hotspot / tethering', 'NFC', 'Airplane mode'], answer: 1, exp: 'A mobile hotspot turns a phone into a wireless access point so other devices can connect to the internet through the phone cellular data. USB tethering does the same thing over a cable.', domain: 'D2' },
  { q: 'What is the primary function of a compiler?', opts: ['Translate source code into machine code before running', 'Run code line by line as it is read', 'Find logic errors in code', 'Format code for readability'], answer: 0, exp: 'A compiler translates an entire program written in a high-level language (like C++) into machine code that the CPU can execute directly. Interpreters, by contrast, translate and run code line by line.', domain: 'D4' },
  { q: 'Which of the following is an example of structured data?', opts: ['A folder full of photos', 'A spreadsheet of student grades organized in rows and columns', 'A voicemail recording', 'A blog post'], answer: 1, exp: 'Structured data follows a predefined format like rows and columns in a spreadsheet or database table. Unstructured data (images, audio, free-text documents) has no rigid schema.', domain: 'D5' },
  { q: 'A user receives a phone call from someone claiming to be from a bank, asking for their account number. What is this attack called?', opts: ['Phishing', 'Vishing', 'Smishing', 'Pharming'], answer: 1, exp: 'Vishing (voice phishing) uses phone calls to trick victims. Smishing uses SMS text messages. Phishing uses email. Legitimate banks will never call to ask for full account credentials.', domain: 'D6' },
  { q: 'What is the difference between a variable and a constant in programming?', opts: ['A variable holds text; a constant holds numbers', 'A variable can change during program execution; a constant cannot', 'A constant is faster than a variable', 'There is no difference'], answer: 1, exp: 'A variable holds a value that can change while the program runs. A constant is assigned once and cannot be reassigned. Constants are useful for fixed values like PI or a tax rate.', domain: 'D4' },
  { q: 'Which troubleshooting step should come FIRST?', opts: ['Establish a theory of probable cause', 'Identify the problem and gather information', 'Test the theory to determine cause', 'Document findings'], answer: 1, exp: 'The CompTIA troubleshooting model begins with identifying the problem by gathering information from the user, observing symptoms, and finding what changed. Jumping to solutions without understanding the problem wastes time.', domain: 'D1' },
  { q: 'A teacher wants to give every student in their class read-only access to a folder of materials. Which permission is MOST appropriate?', opts: ['Full Control', 'Modify', 'Read', 'Write'], answer: 2, exp: 'Read permission allows users to view and open files but not change or delete them. Granting only the minimum required access follows the principle of least privilege.', domain: 'D6' },
  { q: 'Which of the following is an example of personally identifiable information (PII)?', opts: ['A favorite color', 'A Social Security number', 'A list of hobbies', 'A username for a public forum'], answer: 1, exp: 'PII is data that can identify a specific person, such as a Social Security number, driver license number, or date of birth combined with other details. Protecting PII is required by many privacy laws.', domain: 'D6' },
  { q: 'What does the acronym GUI stand for, and what does it provide?', opts: ['General User Information; account details', 'Graphical User Interface; visual icons, windows, and menus for user interaction', 'Generic Universal Interpreter; runs scripts', 'Guided User Installation; setup wizard'], answer: 1, exp: 'A Graphical User Interface (GUI) uses visual elements like icons, windows, and menus so users can interact with a computer by clicking instead of typing commands. Windows and macOS both use GUIs.', domain: 'D4' },
  { q: 'A small business wants to back up files automatically without buying their own server. Which is the BEST option?', opts: ['Email files to themselves daily', 'Use a cloud backup service like OneDrive or Google Drive', 'Print every file as a paper copy', 'Save copies on the same hard drive in a different folder'], answer: 1, exp: 'Cloud backup services automatically sync files to remote servers, protecting against local hardware failure, theft, and disasters. Saving copies on the same drive offers no protection if that drive fails.', domain: 'D6' },
  { q: 'Which of the following is a property of a STRONG password policy?', opts: ['Force users to change passwords every week', 'Require minimum length, complexity, and prohibit reuse of recent passwords', 'Allow users to write passwords on a sticky note', 'Require passwords to match a common dictionary word'], answer: 1, exp: 'Effective password policies enforce a minimum length (12+ characters), some complexity, and prevent reuse of recent passwords. Forcing extremely frequent changes leads to weaker passwords as users add predictable suffixes.', domain: 'D6' },
  { q: 'A student is shopping for a new internet plan and the advertisement says "300 Mbps." What does Mbps measure?', opts: ['Total storage capacity of the modem', 'Network speed in megabits per second', 'Monthly bandwidth allowance in megabytes', 'Distance the Wi-Fi signal reaches'], answer: 1, exp: 'Mbps stands for megabits per second and measures network throughput. Note the lowercase b means bits, not bytes; a 300 Mbps connection transfers roughly 37.5 megabytes per second since 8 bits make 1 byte.', domain: 'D2' },
  { q: 'Which of the following is an example of APPLICATION software?', opts: ['Windows 11', 'macOS Sonoma', 'Microsoft Word', 'A device driver'], answer: 2, exp: 'Application software performs tasks for end users, such as Microsoft Word for writing documents. Windows and macOS are operating systems, and device drivers are system software that lets the OS talk to hardware.', domain: 'D3' },
  { q: 'A user wants to remember many strong, unique passwords without writing them down. Which tool is BEST suited?', opts: ['A spreadsheet on the desktop', 'A reputable password manager', 'The same password reused across sites', 'A note taped to the monitor'], answer: 1, exp: 'Password managers store unique credentials in an encrypted vault unlocked by one master password (ideally with MFA). Reusing passwords or storing them in plaintext on the device defeats the purpose of strong passwords.', domain: 'D6' },
  { q: 'Which of the following BEST describes the role of an IP address?', opts: ['A physical hardware identifier burned into the NIC', 'A logical address used to identify a device on a network', 'The name of a website', 'The encryption key used by a router'], answer: 1, exp: 'An IP address is a logical, software-assigned address that identifies a device on a network and can change (for example, when a device moves networks). A MAC address is the physical hardware identifier.', domain: 'D2' },
  { q: 'A user reports that a webpage will not load, but other sites work fine. What is the FIRST step they should try?', opts: ['Reinstall the operating system', 'Refresh the page and try a different browser to see if the site is reachable', 'Replace the network cable', 'Reset the router to factory defaults'], answer: 1, exp: 'When only one website fails, start with the simplest checks: refresh, clear browser cache, or try another browser. The site itself may be down. Major reinstall or hardware actions are far too aggressive for a single-site issue.', domain: 'D3' },
  { q: 'In a typical home or small office network, which device connects the local network to the internet service provider?', opts: ['Switch', 'Router', 'Access point', 'Hub'], answer: 1, exp: 'A router connects two different networks, typically the home LAN to the ISP. A switch connects devices inside one network. An access point provides wireless connectivity. Many home devices combine all three roles.', domain: 'D2' },
  { q: 'A help desk technician asks a user: "What error message do you see, and what were you doing right before it appeared?" Which troubleshooting step is this?', opts: ['Document findings', 'Identify the problem and gather information', 'Implement the solution', 'Verify full system functionality'], answer: 1, exp: 'Gathering symptoms and recent changes from the user is the first step: identifying the problem. Skipping this step leads to guessing fixes that may not address the actual issue.', domain: 'D1' },
  { q: 'Which of the following is the MOST appropriate first action when an employee leaves a company?', opts: ['Wait a week before changing anything', 'Disable the user\'s accounts and revoke access immediately', 'Delete all of the company\'s files the user worked on', 'Reset the corporate Wi-Fi password'], answer: 1, exp: 'Account disablement should occur on or before the user\'s last day to prevent unauthorized access. Files generally need to be preserved for business continuity, not deleted, and changing the Wi-Fi password does not address the user\'s individual access.', domain: 'D6' },
  { q: 'In programming, what is the purpose of a FUNCTION?', opts: ['To store a single value that never changes', 'To group a block of code that can be reused with different inputs', 'To draw graphics on the screen', 'To encrypt data automatically'], answer: 1, exp: 'A function groups related code into a reusable unit that can take inputs (arguments) and return a result. Functions reduce duplication and make programs easier to read and maintain.', domain: 'D4' },
  { q: 'A user wants to identify a file as a Microsoft Excel spreadsheet at a glance. Which file extension would they look for?', opts: ['.docx', '.xlsx', '.pptx', '.pdf'], answer: 1, exp: 'Modern Excel spreadsheets use the .xlsx extension. .docx is Word, .pptx is PowerPoint, and .pdf is a Portable Document Format file (often read-only). File extensions help the OS associate files with the right application.', domain: 'D3' },
  { q: 'Which of the following is an example of something you ARE for authentication purposes?', opts: ['A password', 'A smart card', 'A fingerprint', 'A PIN'], answer: 2, exp: 'Biometrics like fingerprints, facial recognition, and iris scans are something you ARE. Passwords and PINs are something you know; smart cards and security keys are something you have.', domain: 'D6' },
  { q: 'A small business wants their employees to access the same software through a web browser without installing anything locally. Which cloud service model is this?', opts: ['IaaS', 'PaaS', 'SaaS', 'On-premises'], answer: 2, exp: 'SaaS (Software as a Service) delivers fully managed applications over the internet through a browser. Examples include Microsoft 365 and Google Workspace. IaaS and PaaS provide infrastructure or platforms, not finished applications.', domain: 'D3' },
  { q: 'Which of the following is the BEST example of a STRONG passphrase?', opts: ['Password1!', 'Summer2024', 'qwerty12345', 'Maple-Octopus-Sailboat-9243'], answer: 3, exp: 'Length combined with unrelated words is the dominant factor in resistance to cracking. Common substitutions (P@ssw0rd) and dictionary words with a year are easily brute-forced or guessed by modern attack tools.', domain: 'D6' },
  { q: 'A user complains that their web browser keeps redirecting them to ads and unfamiliar search engines. What is the MOST likely cause?', opts: ['A new printer driver', 'Browser-based adware or a malicious extension', 'A weak Wi-Fi signal', 'An expired warranty on the laptop'], answer: 1, exp: 'Persistent redirects, injected ads, and changed default search engines are classic signs of adware or a malicious browser extension. Removing unfamiliar extensions and running an anti-malware scan are appropriate next steps.', domain: 'D3' },
  { q: 'Which of the following is the BEST description of a relational database table?', opts: ['A folder of unrelated images', 'A collection of records stored in rows and columns with defined fields', 'A document with paragraphs of free text', 'A sequence of system log entries'], answer: 1, exp: 'A relational table organizes data into rows (records) and columns (fields) with a defined schema. This structure allows queries that filter, join, and aggregate data efficiently using SQL.', domain: 'D5' },
  { q: 'Which storage capacity is the LARGEST?', opts: ['500 MB', '2 GB', '1 TB', '750 KB'], answer: 2, exp: 'From smallest to largest: KB, MB, GB, TB. 1 TB is roughly 1,000 GB, which is roughly 1,000,000 MB. The 750 KB option is the smallest of the four.', domain: 'D1' },
  { q: 'A user is asked to provide their Social Security number, full date of birth, and mother\'s maiden name to a caller claiming to be from their bank. What should they do?', opts: ['Provide the information so the bank can verify their identity', 'Hang up and call the bank back using a number from the bank\'s official website', 'Provide only the last four digits', 'Email the information to the caller instead'], answer: 1, exp: 'This is a classic vishing scenario. Legitimate banks never request full identifiers in an unsolicited call. The safe action is to end the call and reach the bank using a verified phone number on the back of a card or the official website.', domain: 'D6' },
  { q: 'Which of the following is a primary benefit of using a CLOUD storage service over a local-only backup?', opts: ['Faster file open times for very large files', 'Files remain accessible if the local device is lost, stolen, or damaged', 'No internet connection is required to access files', 'No account is needed'], answer: 1, exp: 'Cloud storage keeps a copy off-device, protecting against theft, drive failure, and disasters. This aligns with the offsite copy in the 3-2-1 backup rule. Local copies remain faster for very large files.', domain: 'D6' },
  { q: 'In a flowchart, which shape typically represents a process or action step?', opts: ['Oval', 'Rectangle', 'Diamond', 'Parallelogram'], answer: 1, exp: 'Standard flowchart conventions use a rectangle for a process or action, an oval for start and end, a diamond for a decision, and a parallelogram for input or output.', domain: 'D4' },
  { q: 'Which of the following is the BEST description of metadata?', opts: ['The main content of a file', 'Data about data, such as author, created date, and file size', 'A type of compression', 'A backup copy of the file'], answer: 1, exp: 'Metadata describes a file\'s properties, such as who created it, when, and its size or format. Even after content is altered or removed, metadata may persist and reveal information about the file or its origins.', domain: 'D5' },
  { q: 'Which of the following is an example of UNSTRUCTURED data?', opts: ['A table of customer names and phone numbers in a database', 'A spreadsheet of monthly sales', 'A folder of vacation photos and a video', 'A list of products with prices and SKUs'], answer: 2, exp: 'Unstructured data does not follow a predefined schema; examples include images, videos, audio recordings, and free-text documents. Structured data fits neatly into rows and columns with defined fields.', domain: 'D5' },
  { q: 'A user wants to share a single document with a coworker so that both can edit it at the same time and see each other\'s changes. Which approach is BEST?', opts: ['Email the file back and forth as attachments', 'Print and hand the document to the coworker', 'Use a cloud-based document service that supports real-time co-editing', 'Save the file to a USB drive and pass it around'], answer: 2, exp: 'Real-time collaborative editing in services like Microsoft 365 or Google Docs avoids version conflicts that arise from emailing attachments. Both users see edits as they happen and the document has one canonical copy.', domain: 'D2' },
  { q: 'Which of the following is the MOST common reason a software vendor releases a security patch?', opts: ['To add new features that customers requested', 'To fix a vulnerability that could be exploited by an attacker', 'To change the application icon', 'To remove old language translations'], answer: 1, exp: 'Security patches address discovered vulnerabilities. Applying them promptly is one of the most effective and inexpensive defenses. Feature updates are typically separate from security-only patches.', domain: 'D6' },
  { q: 'A user wants to identify a file as an image. Which of the following extensions indicates an image file?', opts: ['.txt', '.mp3', '.jpg', '.exe'], answer: 2, exp: '.jpg (JPEG) is a common image format. .txt is plain text, .mp3 is audio, and .exe is an executable program on Windows. Other image extensions include .png, .gif, .bmp, and .webp.', domain: 'D3' },
  { q: 'Which of the following is the PRIMARY function of an operating system\'s task or process manager?', opts: ['Encrypt the hard drive', 'View running programs and resource usage and end unresponsive tasks', 'Compile source code into machine code', 'Replace the BIOS firmware'], answer: 1, exp: 'A task manager (Task Manager on Windows, Activity Monitor on macOS, top or htop on Linux) displays running processes and their CPU, memory, and disk usage, and can end frozen applications. It does not perform encryption or compilation.', domain: 'D3' },
  { q: 'Which numbering system uses base 16, with digits 0 through 9 and letters A through F?', opts: ['Binary', 'Decimal', 'Hexadecimal', 'Octal'], answer: 2, exp: 'Hexadecimal is base 16. It is widely used in computing because each hex digit maps neatly to four binary bits, making long binary values much shorter and easier to read.', domain: 'D1' },
  { q: 'Why is hexadecimal commonly used to represent values such as colors and MAC addresses?', opts: ['It is the only system computers understand', 'It compactly represents binary, with one hex digit per four bits', 'It is faster for the CPU to process', 'It is the only system that supports negative numbers'], answer: 1, exp: 'One hexadecimal digit equals exactly four binary bits, so hex provides a short, human-readable way to write long binary values such as a color code (FF8800) or a MAC address.', domain: 'D1' },
  { q: 'Which data type would a programmer use to store a person age, such as 17?', opts: ['Integer', 'Boolean', 'String', 'Float'], answer: 0, exp: 'An integer stores whole numbers with no decimal point, which fits an age like 17. Floats store decimals, strings store text, and Booleans store only true or false.', domain: 'D4' },
  { q: 'Which data type stores only one of two values: true or false?', opts: ['Integer', 'Boolean', 'String', 'Float'], answer: 1, exp: 'A Boolean holds true or false and is used for conditions and decisions in code, such as isLoggedIn = true. It is named after mathematician George Boole.', domain: 'D4' },
  { q: 'Which data type would BEST store a customer name such as Maria Lopez?', opts: ['Integer', 'Boolean', 'String', 'Float'], answer: 2, exp: 'A string stores text: letters, numbers, and symbols treated as characters. Names, addresses, and messages are stored as strings. Numeric types are for values used in calculations.', domain: 'D4' },
  { q: 'A program needs to store a product price such as 19.99. Which data type is appropriate?', opts: ['Integer', 'Boolean', 'Float (decimal)', 'Character'], answer: 2, exp: 'A float (or decimal) data type stores numbers with a fractional part, which is required for currency values like 19.99. An integer can only store whole numbers.', domain: 'D4' },
  { q: 'A company pays a recurring monthly fee for each user to access a software product. Which licensing model is this?', opts: ['One-time perpetual license', 'Subscription license', 'Open-source license', 'Public domain'], answer: 1, exp: 'A subscription license grants access for a recurring fee (monthly or yearly). Microsoft 365 is a common example. A perpetual license is bought once and owned indefinitely.', domain: 'D3' },
  { q: 'Software whose source code is kept secret and owned by the company that sells it is BEST described as?', opts: ['Open-source software', 'Proprietary (closed-source) software', 'Freeware that can be modified', 'Public domain software'], answer: 1, exp: 'Proprietary software keeps its source code private and restricts modification and redistribution. Open-source software publishes its code under a license that permits viewing, modifying, and sharing.', domain: 'D3' },
  { q: 'A school purchases a single license agreement that covers every computer on its campus. What type of license is this?', opts: ['Single-use license', 'Site (or volume) license', 'Trial license', 'Concurrent license for one user'], answer: 1, exp: 'A site or volume license covers many installations across an organization or location under one agreement, which is more economical than buying individual single-use licenses for each computer.', domain: 'D3' },
  { q: 'Which of the following is an example of a mobile operating system?', opts: ['Windows 11', 'macOS', 'Android', 'Ubuntu Server'], answer: 2, exp: 'Android (and iOS) are mobile operating systems designed for phones and tablets, with touch interfaces and power efficiency. Windows 11 and macOS are desktop OSs; Ubuntu Server is a server OS.', domain: 'D3' },
  { q: 'An operating system designed to run on a device with limited resources, such as a smart thermostat or a router, is called a(n)?', opts: ['Server operating system', 'Embedded operating system', 'Desktop operating system', 'Virtual operating system'], answer: 1, exp: 'An embedded OS is a compact operating system built into a special-purpose device such as a thermostat, smart TV, or router. It is optimized for that single role rather than general-purpose computing.', domain: 'D3' },
  { q: 'What does a web browser cache store to help pages load faster on return visits?', opts: ['User passwords in plaintext', 'Copies of recently downloaded page resources such as images and scripts', 'The computer operating system', 'Antivirus signatures'], answer: 1, exp: 'The browser cache saves copies of resources like images, stylesheets, and scripts. On a return visit the browser reuses the local copy instead of re-downloading it, which speeds up loading.', domain: 'D3' },
  { q: 'What are browser cookies primarily used for?', opts: ['Speeding up the CPU', 'Storing small pieces of site data such as login sessions and preferences', 'Encrypting the hard drive', 'Blocking advertisements'], answer: 1, exp: 'Cookies are small files a website stores in the browser to remember information such as a logged-in session, language choice, or items in a shopping cart between page visits.', domain: 'D3' },
  { q: 'A user opens a private (incognito) browsing window. What does this mode actually do?', opts: ['Makes the user completely anonymous to websites and their employer', 'Prevents the browser from saving history, cookies, and form data locally after the session', 'Encrypts all internet traffic', 'Blocks all malware automatically'], answer: 1, exp: 'Private browsing simply avoids saving local history, cookies, and form data once the window closes. It does NOT hide activity from the network, the ISP, or the websites visited.', domain: 'D6' },
  { q: 'HTML, used to structure the content of web pages, is BEST described as which type of language?', opts: ['Compiled programming language', 'Markup language', 'Query language', 'Assembly language'], answer: 1, exp: 'HTML is a markup language: it uses tags to describe the structure and content of a document rather than performing logic or calculations. SQL is a query language; C++ is a compiled programming language.', domain: 'D4' },
  { q: 'Python code is executed line by line at run time without a separate build step. This makes Python a(n)?', opts: ['Compiled language', 'Interpreted language', 'Markup language', 'Machine language'], answer: 1, exp: 'An interpreted language is translated and executed line by line by an interpreter at run time. A compiled language is converted entirely to machine code before it runs.', domain: 'D4' },
  { q: 'Writing out the logic of a program in plain, structured language before writing actual code is called?', opts: ['Compiling', 'Pseudocode', 'Debugging', 'Encrypting'], answer: 1, exp: 'Pseudocode expresses program logic in plain language so it can be planned and reviewed before being written in a specific programming language. It is not run by a computer.', domain: 'D4' },
  { q: 'Which programming structure stores an ordered collection of multiple values under a single name, accessed by index?', opts: ['Variable', 'Constant', 'Array', 'Function'], answer: 2, exp: 'An array (or list) holds many values in one named structure, each reachable by its position (index). It is ideal for collections such as a list of test scores.', domain: 'D4' },
  { q: 'An IF statement that runs one block of code when a condition is true and another when it is false is an example of?', opts: ['Looping', 'Branching (selection)', 'A constant', 'Compiling'], answer: 1, exp: 'Branching, also called selection, chooses between paths based on a condition. Looping repeats code. Together, branching and looping are the core building blocks of program control flow.', domain: 'D4' },
  { q: 'Which database field uniquely identifies each record in a table so that no two rows are the same?', opts: ['Foreign key', 'Primary key', 'Index field', 'Default field'], answer: 1, exp: 'A primary key is a field (or set of fields) whose value is unique for every record, such as a student ID. It guarantees each row can be distinctly identified.', domain: 'D5' },
  { q: 'In a database table, a single row that represents one complete entity, such as one student, is called a?', opts: ['Field', 'Record', 'Query', 'Schema'], answer: 1, exp: 'A record (row) holds all the data about one item. A field (column) holds one attribute, such as last name. The record is the collection of all fields for that single entity.', domain: 'D5' },
  { q: 'A single spreadsheet-style file that stores data with no relationships to other files is an example of a?', opts: ['Relational database', 'Flat file database', 'Cloud database', 'Distributed database'], answer: 1, exp: 'A flat file database stores data in one table or file with no links to others. It is simple but does not handle complex relationships. Relational databases connect multiple related tables.', domain: 'D5' },
  { q: 'Which type of database stores information as documents or key-value pairs rather than in fixed rows and columns?', opts: ['Relational (SQL) database', 'Non-relational (NoSQL) database', 'Flat file database', 'Spreadsheet'], answer: 1, exp: 'Non-relational (NoSQL) databases store data flexibly as documents, key-value pairs, or graphs, which suits unstructured or rapidly changing data. Relational databases use structured tables with a fixed schema.', domain: 'D5' },
  { q: 'Ensuring that systems and data are accessible when authorized users need them describes which part of the CIA triad?', opts: ['Confidentiality', 'Integrity', 'Availability', 'Authentication'], answer: 2, exp: 'Availability means information and services are reachable when needed. Backups, redundancy, and reliable infrastructure support it. Confidentiality limits disclosure; integrity ensures data is unaltered.', domain: 'D6' },
  { q: 'Ensuring that data has not been changed or tampered with describes which part of the CIA triad?', opts: ['Confidentiality', 'Integrity', 'Availability', 'Authorization'], answer: 1, exp: 'Integrity means data remains accurate and unaltered except by authorized changes. Hashing and checksums help verify integrity. Confidentiality prevents disclosure; availability ensures access.', domain: 'D6' },
  { q: 'Encrypting the files stored on a laptop hard drive protects the data while it is in which state?', opts: ['Data in transit', 'Data at rest', 'Data in use', 'Data in motion'], answer: 1, exp: 'Data at rest is data stored on a device or media. Full-disk encryption protects it if the device is lost or stolen. Data in transit (protected by HTTPS or a VPN) is data moving across a network.', domain: 'D6' },
  { q: 'In security, verifying WHO a user is constitutes authentication. What is the term for determining WHAT that user is allowed to access?', opts: ['Authorization', 'Accounting', 'Auditing', 'Encryption'], answer: 0, exp: 'Authorization decides what an authenticated user may do or access, based on permissions. Authentication proves identity first; accounting then logs what the user actually did.', domain: 'D6' },
  { q: 'Which of the following is a recommended device-hardening practice?', opts: ['Leave all default passwords unchanged', 'Install security updates, enable the firewall, and remove software that is not needed', 'Disable antivirus to improve speed', 'Share one admin account among all users'], answer: 1, exp: 'Hardening reduces a device attack surface: apply updates, enable the firewall, remove unnecessary software and services, and change default credentials. The other options weaken security.', domain: 'D6' },
  { q: 'What is the safest practice when downloading and installing new software?', opts: ['Download from any site that appears in a search', 'Download only from the official vendor site or a trusted app store', 'Disable the firewall first so it installs faster', 'Always choose software sent as an email attachment'], answer: 1, exp: 'Official vendor sites and reputable app stores vet their software. Downloads from random sites or unexpected email attachments are a common malware delivery method and should be avoided.', domain: 'D3' },
  { q: 'Which port is most commonly used to connect peripherals such as a keyboard, mouse, or flash drive to a computer?', opts: ['HDMI', 'USB', 'Ethernet (RJ-45)', 'VGA'], answer: 1, exp: 'USB (Universal Serial Bus) is the standard, general-purpose port for connecting peripherals. HDMI carries video and audio, Ethernet connects to networks, and VGA is an older video-only connector.', domain: 'D2' },
  { q: 'Which connector carries both high-definition video and audio to a monitor or TV over a single cable?', opts: ['USB-A', 'HDMI', 'Ethernet', '3.5 mm audio jack'], answer: 1, exp: 'HDMI (High-Definition Multimedia Interface) transmits both digital video and audio on one cable, which is why it is the common choice for connecting computers, consoles, and players to displays.', domain: 'D2' },
  { q: 'Which of the following is a peripheral device?', opts: ['The CPU', 'The motherboard', 'A printer', 'System RAM'], answer: 2, exp: 'A peripheral is an external device that connects to and works with a computer, such as a printer, keyboard, mouse, or webcam. The CPU, motherboard, and RAM are internal core components.', domain: 'D2' },
  { q: 'Which component allows a computer to connect to a wired or wireless network?', opts: ['GPU', 'Network interface card (NIC)', 'Power supply', 'Sound card'], answer: 1, exp: 'The network interface card (NIC) provides the connection to a network, wired (Ethernet) or wireless (Wi-Fi). Each NIC has a unique MAC address.', domain: 'D2' },
  { q: 'Which component is primarily responsible for rendering images, video, and 3D graphics?', opts: ['CPU', 'GPU (graphics processing unit)', 'RAM', 'Hard drive'], answer: 1, exp: 'The GPU specializes in the parallel calculations needed to render graphics and video, and increasingly to accelerate tasks like machine learning. The CPU handles general-purpose processing.', domain: 'D2' },
  { q: 'An external USB hard drive that a user carries between computers is an example of?', opts: ['Internal storage', 'External (portable) storage', 'Volatile memory', 'Cloud storage'], answer: 1, exp: 'External storage connects outside the computer case, typically by USB, and is portable. Internal storage is installed inside the case. Both are non-volatile, unlike RAM.', domain: 'D2' },
  { q: 'What is the primary function of DNS (Domain Name System)?', opts: ['Encrypt web traffic', 'Translate human-readable domain names into IP addresses', 'Assign IP addresses to devices automatically', 'Block malicious websites'], answer: 1, exp: 'DNS works like the internet phone book, translating a name such as example.com into the numeric IP address computers use to locate the server. Without DNS, users would need to memorize IP addresses.', domain: 'D2' },
  { q: 'What does DHCP (Dynamic Host Configuration Protocol) do on a network?', opts: ['Encrypts files on the server', 'Automatically assigns IP addresses and network settings to devices', 'Translates domain names to IP addresses', 'Filters spam email'], answer: 1, exp: 'DHCP automatically gives each device that joins a network an IP address, subnet mask, gateway, and DNS server, so users do not have to configure these settings manually.', domain: 'D2' },
  { q: 'Which wireless technology is BEST suited for connecting wireless earbuds to a smartphone over a very short range?', opts: ['Wi-Fi', 'Bluetooth', 'Cellular data', 'NFC'], answer: 1, exp: 'Bluetooth is designed for short-range connections between personal devices such as earbuds, keyboards, and speakers, using low power. Wi-Fi covers a larger area and is used for network and internet access.', domain: 'D2' },
  { q: 'Which device converts the signal from an internet service provider into a signal a home network can use?', opts: ['Switch', 'Modem', 'Access point', 'Repeater'], answer: 1, exp: 'A modem connects the home to the ISP, converting between the provider signal (cable, fiber, DSL) and a standard network signal. A router then shares that connection among devices.', domain: 'D2' },
  { q: 'Why should important files be backed up regularly?', opts: ['Backups make the computer run faster', 'So data can be recovered if it is lost to hardware failure, theft, ransomware, or accidental deletion', 'Backups are required to install software', 'Backups increase internet speed'], answer: 1, exp: 'Regular backups provide a recovery option when the original data is lost. Hardware fails, devices are stolen, ransomware encrypts files, and users delete things by mistake. A backup is the safety net.', domain: 'D6' },
  { q: 'A server is built with two power supplies so that it keeps running if one supply fails. This design demonstrates?', opts: ['Encryption', 'Fault tolerance (redundancy)', 'Compression', 'Virtualization'], answer: 1, exp: 'Fault tolerance uses redundant components so a single failure does not cause an outage. Dual power supplies, RAID arrays, and clustered servers are common examples of building in redundancy.', domain: 'D6' },
  { q: 'The 3-2-1 backup rule recommends keeping how many copies of important data?', opts: ['1 copy on the same drive', '2 copies, both on the same computer', '3 copies, on 2 types of media, with 1 copy stored offsite', '5 copies, all in the cloud'], answer: 2, exp: 'The 3-2-1 rule means 3 total copies of the data, stored on 2 different types of media, with at least 1 copy kept offsite. This protects against device failure, local disasters, and theft.', domain: 'D6' },
  { q: 'Why do businesses treat the data they collect as a valuable asset?', opts: ['Data takes up disk space that can be sold', 'Data can be analyzed to support informed, data-driven business decisions', 'Data automatically generates income', 'Data replaces the need for employees'], answer: 1, exp: 'Organizations analyze data to understand customers, spot trends, and make better decisions. Well-managed data is a strategic asset, which is also why protecting it matters.', domain: 'D1' },
  { q: 'Copying and reselling a company copyrighted software without permission is a violation of?', opts: ['An acceptable use policy only', 'Intellectual property rights (copyright)', 'A service level agreement', 'Net neutrality'], answer: 1, exp: 'Software, music, writing, and designs are protected as intellectual property. Copying or reselling them without authorization infringes copyright and can carry legal penalties.', domain: 'D3' },
  { q: 'After resolving a problem, what should a technician do BEFORE documenting the findings?', opts: ['Immediately close the ticket', 'Verify full system functionality and confirm the issue is truly resolved', 'Establish a new theory of cause', 'Reinstall the operating system'], answer: 1, exp: 'Verifying full system functionality confirms the fix worked and did not cause new issues. Only after verification should the technician document the findings, actions, and outcome.', domain: 'D3' },
  { q: 'You log in to your email with a password and then enter a 6-digit code from your authenticator app. Which BEST describes this login?', opts: ['Single-factor authentication', 'Multi-factor authentication using "something you know" and "something you have"', 'A password manager', 'Single sign-on'], answer: 1, exp: 'A password is "something you know" and a code from an app on your phone is "something you have." Two different factor types = multi-factor authentication. Two passwords would still be single-factor.', domain: 'D6' },
  { q: 'Which type of authentication factor is a fingerprint?', opts: ['Something you know', 'Something you have', 'Something you are', 'Something you do'], answer: 2, exp: 'Biometrics like fingerprints, face, and iris scans are "something you are." Passwords and PINs are "something you know"; phones and security keys are "something you have."', domain: 'D6' },
  { q: 'A friend asks you to share your streaming-service password so they can watch a show. What is the BEST response?', opts: ['Share it — it is only a streaming account', 'Decline; passwords should not be shared. Suggest a guest profile or the household plan', 'Share it but change the password later', 'Share only half the password by text and half by phone'], answer: 1, exp: 'Sharing passwords undermines accountability and often violates terms of service. It also exposes you if the friend reuses or leaks it. Most services offer family plans or guest profiles instead.', domain: 'D6' },
  { q: 'Which password practice is MOST recommended today?', opts: ['Use the same strong password on every account so you can remember it', 'Use a unique long passphrase per account, stored in a password manager, plus MFA where supported', 'Change every password every 30 days regardless', 'Write all passwords on a sticky note attached to the monitor'], answer: 1, exp: 'Modern guidance: long unique passwords per account, managed by a password manager, with MFA on important accounts. Reuse means one site breach leaks many accounts. Forced 30-day rotations push users toward weaker passwords; sticky notes are obvious.', domain: 'D6' },
  { q: 'You set up SMS-based two-factor authentication on your email. Why is this WEAKER than an authenticator app?', opts: ['SMS uses more battery', 'SMS codes are typed faster', 'SIM-swap attacks can redirect your text messages to an attacker', 'Authenticator apps need the internet to generate codes'], answer: 2, exp: 'In a SIM-swap attack, a scammer convinces a carrier to transfer your phone number to their SIM and intercepts your text messages — including 2FA codes. Authenticator apps generate codes on the device itself, without using the phone number.', domain: 'D6' },
  { q: 'You see a small padlock icon in your browser address bar. What does it tell you?', opts: ['The website was reviewed and approved by the government', 'The connection to the site is encrypted (HTTPS) and the certificate matches the domain', 'The site has no advertisements', 'The site cannot contain malware'], answer: 1, exp: 'The padlock confirms HTTPS encryption and that the cert is valid for the domain — that is all. Phishing sites can also get free HTTPS certs (Let’s Encrypt). The padlock is necessary, but not sufficient, for trust.', domain: 'D3' },
  { q: 'Your browser shows "Your connection is not private — NET::ERR_CERT_AUTHORITY_INVALID" when you visit your bank. What should you do?', opts: ['Click "Proceed anyway" to get to your account', 'Refresh the page until the warning goes away', 'Stop. Do NOT enter credentials. Verify the URL or open the bank from a trusted bookmark', 'Disable the antivirus and retry'], answer: 2, exp: 'A certificate-authority error means the cert was issued by something your browser does not trust (an attacker, a misconfigured proxy, etc.). Never enter credentials on a page showing this warning. Open the site from a known-good bookmark instead.', domain: 'D3' },
  { q: 'Which URL is MOST suspicious for a "PayPal" login link?', opts: ['paypal.com', 'www.paypal.com', 'paypal.com/signin', 'paypal-secure-login.com'], answer: 3, exp: 'Phishing sites use look-alike domains like "paypal-secure-login.com" that have nothing to do with the real paypal.com. Always inspect the actual domain — the part right before the first single slash — not the subdomain or path.', domain: 'D6' },
  { q: 'You receive an urgent text that says "Your bank account has been locked. Click here to verify." What is the BEST first action?', opts: ['Click the link to confirm the alert', 'Reply with your account number', 'Ignore the link and visit your bank directly from your saved bookmark or app', 'Forward it to your contacts'], answer: 2, exp: 'Urgency + a link is classic phishing (and smishing when it arrives as a text). Never follow the link in the message. Open the bank from your saved bookmark or official app — if there is a real issue, you will see it there.', domain: 'D6' },
  { q: 'A caller claims to be from IT and asks you to read your password aloud so they can "verify your account." What should you do?', opts: ['Read the password — IT needs to verify it', 'Spell the password slowly so they get it right', 'Refuse; legitimate IT never needs your password. Hang up and report the call', 'Read the password backwards as a precaution'], answer: 2, exp: 'No legitimate IT process requires reading your password aloud. This is a classic social engineering (vishing) attack. Hang up, do not share the password, and report the call to your real IT or security team.', domain: 'D6' },
  { q: 'Your computer displays a message demanding payment in cryptocurrency to unlock your files. What kind of malware is this?', opts: ['Adware', 'Ransomware', 'Spyware', 'Worm'], answer: 1, exp: 'Ransomware encrypts your files and demands payment for the decryption key. It often arrives through phishing or unpatched software. Backups + caution + updates are the main defenses; paying does not guarantee recovery.', domain: 'D6' },
  { q: 'You think you just clicked a phishing link and entered your credentials. What is the FIRST step you should take?', opts: ['Restart the computer', 'Disconnect from the network, then change the affected password from a different, clean device', 'Tell no one and hope nothing happens', 'Empty the recycle bin'], answer: 1, exp: 'Disconnect first to stop further data loss or lateral movement. Then change the password from a clean device so the change is not captured by anything still on the original machine. Notify IT or the service provider afterward.', domain: 'D6' },
  { q: 'Which backup approach follows the 3-2-1 rule?', opts: ['One copy on the laptop only', 'Three copies on the same external drive', 'Three copies of important data: two on different media types (e.g., laptop + external SSD), one offsite (e.g., cloud or different building)', 'Hourly snapshots on the same disk only'], answer: 2, exp: 'The 3-2-1 rule: 3 total copies of the data, on 2 different types of media, with at least 1 copy kept offsite. It protects against drive failure, ransomware, fire, theft, and accidental deletion all at once.', domain: 'D6' },
  { q: 'Software updates and patches are MOST important because they:', opts: ['Make the screen brighter', 'Fix security vulnerabilities that attackers actively exploit', 'Increase the amount of RAM in the system', 'Are required for the device to boot'], answer: 1, exp: 'Patches close known security holes that attackers scan for. Unpatched software is one of the most common entry points for malware. Enabling automatic updates is the simplest highest-impact thing most users can do.', domain: 'D3' },
  { q: 'Which behavior is the STRONGEST red flag that an email is a phishing attempt?', opts: ['It uses your first name', 'It includes a company logo', 'It urgently asks you to confirm credentials, payment info, or click a link RIGHT NOW', 'It arrives during business hours'], answer: 2, exp: 'Urgency combined with a request to confirm credentials or click a link is the most consistent phishing pattern. Real institutions rarely use that pressure; if there is a real issue, you can always navigate to the site yourself.', domain: 'D6' },
];
